import { normalizeWikiTitle, parseWikiLinks, type WikiLink } from '@backlogger/shared';
import type { Db } from '../db/database.js';
import { pendingDeletionCovers } from '../db/operations-repo.js';

export interface BacklinkRow {
  id: string;
  project_id: string;
  title: string;
  display: string;
  position: number;
}

/**
 * Maintains the `links` table: outgoing wiki-links per document plus the
 * lazy resolution from `target_title` to `target_id`.
 *
 * Filesystem (Markdown body) remains source of truth — every row in this
 * table can be regenerated by walking the body again.
 */
export class LinkService {
  private readonly insertLink;
  private readonly deleteForSource;
  private readonly resolveByTitle;
  private readonly refreshByTitle;
  private readonly listBacklinks;
  private readonly listTitles;
  private readonly listTitlesByProject;
  private readonly clearForId;

  constructor(private readonly db: Db) {
    this.insertLink = db.prepare(
      `INSERT INTO links (source_id, target_id, target_title, target_title_norm, display, position)
       VALUES (@source_id, @target_id, @target_title, @target_title_norm, @display, @position)`,
    );
    this.deleteForSource = db.prepare(`DELETE FROM links WHERE source_id = ?`);
    this.resolveByTitle = db.prepare<[string], { id: string }>(
      `SELECT id FROM documents
        WHERE LOWER(title) = ?
        ORDER BY updated_at DESC
        LIMIT 1`,
    );
    this.refreshByTitle = db.prepare(
      `UPDATE links
          SET target_id = (
            SELECT id FROM documents
             WHERE LOWER(title) = ?
             ORDER BY updated_at DESC
             LIMIT 1
          )
        WHERE target_title_norm = ?`,
    );
    this.listBacklinks = db.prepare<[string], BacklinkRow>(
      `SELECT DISTINCT
              d.id          AS id,
              d.project_id  AS project_id,
              d.title       AS title,
              l.display     AS display,
              l.position    AS position
         FROM links l
         JOIN documents d ON d.id = l.source_id
        WHERE l.target_id = ? AND NOT ${pendingDeletionCovers('d')}
        ORDER BY d.title`,
    );
    this.listTitles = db.prepare<[], { id: string; project_id: string; title: string }>(
      `SELECT id, project_id, title FROM documents d
        WHERE NOT ${pendingDeletionCovers('d')} ORDER BY title`,
    );
    this.listTitlesByProject = db.prepare<
      [string],
      { id: string; project_id: string; title: string }
    >(
      `SELECT id, project_id, title FROM documents d
        WHERE project_id = ? AND NOT ${pendingDeletionCovers('d')} ORDER BY title`,
    );
    this.clearForId = db.prepare(
      `UPDATE links SET target_id = NULL WHERE target_id = ?`,
    );
  }

  /**
   * Re-extract wiki links from a document body, replace the rows for
   * `sourceId`, and resolve each title to a `target_id` if possible.
   *
   * Then refresh resolution for any rows previously pointing at the OLD or
   * NEW title of this document (so a rename re-links cleanly).
   */
  rebuildForDocument(
    sourceId: string,
    title: string,
    body: string,
    previousTitle?: string,
  ): void {
    const links = parseWikiLinks(body);
    const tx = this.db.transaction(() => {
      this.deleteForSource.run(sourceId);
      for (const link of links) {
        const norm = normalizeWikiTitle(link.title);
        const resolved = this.resolveByTitle.get(norm);
        this.insertLink.run({
          source_id: sourceId,
          target_id: resolved?.id ?? null,
          target_title: link.title,
          target_title_norm: norm,
          display: link.display,
          position: link.position,
        });
      }
      // After writing this doc's outgoing links, re-resolve any rows that
      // referenced this doc's title (under either its new or its old name).
      const titles = new Set<string>([normalizeWikiTitle(title)]);
      if (previousTitle) titles.add(normalizeWikiTitle(previousTitle));
      for (const t of titles) {
        this.refreshByTitle.run(t, t);
      }
    });
    tx();
  }

  /** Backlinks for a given document id (deduped by source). */
  backlinksFor(targetId: string): BacklinkRow[] {
    return this.listBacklinks.all(targetId);
  }

  /** Title catalog used by editor autocomplete. */
  titles(projectId?: string): Array<{ id: string; project_id: string; title: string }> {
    return projectId ? this.listTitlesByProject.all(projectId) : this.listTitles.all();
  }

  /**
   * Re-resolve link rows after a document is deleted. ON DELETE SET NULL
   * already clears `target_id`, but the rows remain pointing at this title
   * so any future doc with the same title will be picked up automatically
   * (via the normal `rebuildForDocument` refresh path).
   */
  onDocumentDeleted(targetId: string): void {
    this.clearForId.run(targetId);
  }

  /** Wipe everything; used by reindex before repopulating. */
  truncate(): void {
    this.db.exec(`DELETE FROM links`);
  }

  /** Used by tests only. */
  _peek(sourceId: string): Array<{ target_id: string | null; target_title: string }> {
    return this.db
      .prepare<[string], { target_id: string | null; target_title: string }>(
        `SELECT target_id, target_title FROM links WHERE source_id = ? ORDER BY position`,
      )
      .all(sourceId);
  }

  /** Exposed for callers that want to see resolution without going through rebuild. */
  resolveTitle(title: string): string | null {
    const norm = normalizeWikiTitle(title);
    if (!norm) return null;
    const row = this.resolveByTitle.get(norm);
    return row?.id ?? null;
  }

  /** Returned for type completeness. */
  static parseLinks(body: string): WikiLink[] {
    return parseWikiLinks(body);
  }
}
